/** Triggers a browser download for generated bytes. */
export const downloadBytes = (bytes: Uint8Array, fileName: string, mimeType: string): void => {
  const blob = new Blob([bytes.slice().buffer as ArrayBuffer], {type: mimeType});
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = fileName;
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  // Revoking immediately can cancel the download in some browsers.
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
};

export const XLSX_MIME =
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
export const APKG_MIME = 'application/octet-stream';
export const ZIP_MIME = 'application/zip';

/** Filesystem-safe base name derived from the source document. */
export const exportBaseName = (fileName: string): string =>
  (fileName.replace(/\.[^.]+$/, '') || 'flashcards')
    .replace(/[^\w\s-]+/g, '')
    .trim()
    .replace(/\s+/g, '-')
    .slice(0, 60) || 'flashcards';
